{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 공영주차장 장애인 할인 여부(장애인 주차표지 부착 어머니 차량, 본인 단독 운전, 어머니 등록증 소지)",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "제7조제1항제1호가목은 장애인자동차표지를 부착하고 장애인이 탑승하여 장애인등록증을 제시한 경우에 주차요금의 100분의 80을 할인하도록 정하고 있다. 질문 상황은 장애인 본인이 탑승하지 않고 자녀가 혼자 운전한 경우이므로, 위 감면 요건(장애인 탑승·등록증 제시)을 충족하지 않아 이 호의 장애인 할인은 적용되지 않는다. 다만, 주차시간측정계기 또는 바로녹색결제시스템으로 자격이 확인되는 이용자는 증빙서류를 제시하지 않고 감면받을 수 있다는 규정은 있으나, 이는 각 호의 자격 확인을 전제로 하므로 탑승 요건이 충족되지 않으면 적용되지 않는다.",
          "b_ids": "주차장:제7조제1항, 주차장:제7조제1항제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
